CREATE POLICY "Authenticated can read forum media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'forum-media');
CREATE POLICY "Admins can upload forum media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'forum-media' AND private.has_role(auth.uid(),'admin'::app_role));
CREATE POLICY "Admins can update forum media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'forum-media' AND private.has_role(auth.uid(),'admin'::app_role)) WITH CHECK (bucket_id = 'forum-media' AND private.has_role(auth.uid(),'admin'::app_role));
CREATE POLICY "Admins can delete forum media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'forum-media' AND private.has_role(auth.uid(),'admin'::app_role));